function validate([bottom, top, special]) {
  if (!Number.isInteger(bottom) || !Number.isInteger(top) || bottom < 1 || top > 1000000000 || bottom > top) return 'Need 1 <= bottom <= top <= 10^9.';
  if (!Array.isArray(special) || special.length < 1 || special.length > 100000) return 'special needs 1 to 10^5 floors.';
  if (special.some(v => !Number.isInteger(v) || v < bottom || v > top)) return 'Every special floor lies between bottom and top.';
  if (new Set(special).size !== special.length) return 'Special floors must be distinct.';
  return null;
}

