function maxConsecutive(bottom, top, special) {
  // A free run starts at bottom or just above a special floor; it ends just below the next special floor above it, or at top.
  const reserved = new Set(special);
  let longest = 0;
  for (const start of [bottom, ...special.map(s => s + 1)]) {
    if (start > top || reserved.has(start)) continue;
    let end = top;
    for (const s of special) if (s > start && s - 1 < end) end = s - 1;
    longest = Math.max(longest, end - start + 1);
  }
  return longest;
}

