function generate(rand, size) {
  if (size === 'large') {
    const bottom = 1 + Math.floor(rand() * 1000);
    const top = 1000000000 - Math.floor(rand() * 1000);
    const n = 2000;
    const picked = new Set();
    while (picked.size < n) picked.add(bottom + Math.floor(rand() * (top - bottom + 1)));
    return [bottom, top, [...picked]];
  }
  const bottom = 1 + Math.floor(rand() * 10);
  const top = bottom + Math.floor(rand() * 15);
  const span = top - bottom + 1;
  const n = 1 + Math.floor(rand() * Math.min(span, 6));
  const picked = new Set();
  // Sometimes reserve one of the ends so the edge runs are tested too.
  if (rand() < 0.3) picked.add(rand() < 0.5 ? bottom : top);
  while (picked.size < n) picked.add(bottom + Math.floor(rand() * span));
  return [bottom, top, [...picked]];
}
